#!/usr/bin/env python3
"""Write CFW disk-image fixtures into a directory.

The images are regular files generated by the Rust helper in this folder.
This script never opens, reads, or writes a physical disk. A path under
/dev or a Windows PhysicalDrive path is refused before cargo runs.
"""

from __future__ import annotations

import os
import stat
import subprocess
import sys


def is_physical(path: str) -> bool:
    """True for a physical-disk path. Lexical only: no stat and no open.

    The path is judged as written, before ``abspath``. On Windows,
    ``abspath("/dev/sda")`` becomes ``<drive>\\dev\\sda`` and would hide the
    prefix.
    """
    raw = path.strip()
    low = raw.lower()
    if "physicaldrive" in low:
        return True
    slash = low.replace("\\", "/")
    if slash.startswith("//./") or slash.startswith("//?/"):
        return True
    if _is_device_root(slash):
        return True
    normalized = os.path.normpath(os.path.abspath(raw)).replace("\\", "/")
    return _is_device_root(normalized.lower())


def _is_device_root(slash: str) -> bool:
    if slash in {"/dev", "/proc", "/sys"}:
        return True
    if slash.startswith("/dev/") or slash.startswith("/proc/") or slash.startswith("/sys/"):
        return True
    parts = [part for part in slash.split("/") if part and part != "."]
    if parts and parts[0].endswith(":"):
        parts = parts[1:]
    return bool(parts) and parts[0] in {"dev", "proc", "sys"}


def refuse_existing_special(path: str) -> bool:
    if not os.path.lexists(path):
        return False
    mode = os.lstat(path).st_mode
    return stat.S_ISLNK(mode) or stat.S_ISBLK(mode) or stat.S_ISCHR(mode)


def main() -> int:
    if len(sys.argv) != 2 or sys.argv[1] in {"-h", "--help"}:
        print("usage: build-images.py <output-directory>", file=sys.stderr)
        return 1
    out = sys.argv[1]
    if is_physical(out) or refuse_existing_special(out):
        print(f"refusing a physical disk path: {out}", file=sys.stderr)
        return 2
    os.makedirs(out, exist_ok=True)
    if refuse_existing_special(out) or not os.path.isdir(out):
        print(f"refusing a physical disk path: {out}", file=sys.stderr)
        return 2
    src_tauri = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
    env = os.environ.copy()
    env["CFW_FIXTURE_OUT"] = os.path.abspath(out)
    completed = subprocess.run(
        [
            "cargo",
            "test",
            "--manifest-path",
            os.path.join(src_tauri, "Cargo.toml"),
            "--test",
            "disk_fixtures",
            "write_fixture_images",
            "--",
            "--ignored",
            "--exact",
        ],
        cwd=src_tauri,
        env=env,
        check=False,
    )
    if completed.returncode != 0:
        return completed.returncode
    expected = [
        "boot-armed-original.img",
        "boot-armed-clone.img",
        "boot-disarmed-original.img",
        "boot-disarmed-clone.img",
        "wrap-card.img",
        "wrap-card.txt",
    ]
    for name in expected:
        path = os.path.join(out, name)
        if refuse_existing_special(path) or not stat.S_ISREG(os.lstat(path).st_mode):
            print(f"refusing a physical disk path: {path}", file=sys.stderr)
            return 2
        if os.path.getsize(path) <= 0:
            print(f"fixture {path} is empty", file=sys.stderr)
            return 1
        print(path)
    return 0


if __name__ == "__main__":
    sys.exit(main())
